      // First call in a quiet period fires immediately; subsequent calls
      // inside the cooldown window are ignored (the timer is NOT reset).
      if (timeoutId === undefined) {
        invoke();
        timeoutId = setTimeout(() => {
          timeoutId = undefined;
        }, ms);
      }
    } else {
      // Trailing edge: each new call restarts the wait, and the invocation
      // uses the most recent `this` and arguments.
      if (timeoutId !== undefined) {
        clearTimeout(timeoutId);
      }
      timeoutId = setTimeout(() => {
        timeoutId = undefined;
        invoke();
      }, ms);
    }
  } as T & { cancel(): void };

  debounced.cancel = () => {
    if (timeoutId !== undefined) {
      clearTimeout(timeoutId);
      timeoutId = undefined;
    }
  };

  return debounced;
}
```

### Behavior

- **Trailing by default** — after the last call, `fn` runs once with the latest `this` and arguments after `ms` milliseconds of inactivity.
- **`{ leading: true }`** — the first call in a quiet period runs immediately; further calls within the next `ms` are suppressed without extending the cooldown.
- **`cancel()`** — clears any pending timeout. In trailing mode this cancels the scheduled invocation; in leading mode it ends the cooldown early so the next call fires immediately again.
- **Type-safe** — preserves `this` via `ThisParameterType<T>` and arguments via `Parameters<T>`, and uses only built-in `setTimeout`/`clearTimeout` (no external dependencies).
